try {
    let html = $input.item.json.data || $input.item.json.body; 

    let szukanyIndeks = $('Loop Over Items').first().json.Informacja; 

    if (!html) {
        return { error: 'Brak danych HTML w wejściu.' };
    }
    if (!szukanyIndeks) {
        return { error: "Nie udało się znaleźć pola 'kod_czesci' w węźle 'BAG'." };
    }

    if (typeof html !== 'string') {
        html = String(html);
    }

    szukanyIndeks = String(szukanyIndeks).trim();

    const cheerio = require('cheerio');

    const $ch = cheerio.load(html);

    const wyciagnijLiczbe = (tekst) => {
        if (!tekst) return null;
        const oczyszczony = tekst.replace(',', '.').replace(/[^0-9.-]+/g, '');
        return oczyszczony ? parseFloat(oczyszczony) : null;
    };

    let znalezionyProdukt = null;

    $ch('#tableKartoteka tbody tr').each((index, element) => {
        const wiersz = $ch(element);
        const indeksNaStronie = wiersz.find('td.indeks').text().trim();

        if (indeksNaStronie.endsWith(szukanyIndeks)) {
            const tds = wiersz.find('td');

            if (tds.length >= 9) {
                znalezionyProdukt = {
                    id_wewnetrzne: $ch(tds[0]).text().trim(),
                    cena_netto: wyciagnijLiczbe($ch(tds[1]).text()), 
                    cena_brutto: wyciagnijLiczbe($ch(tds[2]).text()),
                    indeks: indeksNaStronie,
                    nazwa: $ch(tds[5]).text().trim(),
                    producent: $ch(tds[6]).text().trim(),
                    stan_magazynowy: wyciagnijLiczbe($ch(tds[8]).text()) || $ch(tds[8]).text().trim() 
                };

                return false; 
            }
        }
    });

    if (znalezionyProdukt) {
        return [znalezionyProdukt];
    } else {
        return []; 
    }

} catch (error) {
    return { error: `Wystąpił krytyczny błąd: ${error.message}` };
}

